import React from 'react';
import {Flex, Text} from '@gravity-ui/uikit';
import {MarkdownEditorView, useMarkdownEditor} from '@gravity-ui/markdown-editor';

export type MarkdownFieldHandle = {
  getValue: () => string;
  clear: () => void;
};

type MarkdownFieldProps = {
  label: string;
  /** Called on every document change with the current markdown markup. */
  onChange?: (value: string) => void;
  error?: string;
  minHeight?: number;
};

/**
 * Markdown field: the user types markdown syntax (`**bold**`, `# Heading`, `- list`)
 * and sees the formatting immediately (WYSIWYG mode). The toolbar/settings allow switching
 * to the raw markup mode.
 */
export const MarkdownField = React.forwardRef<MarkdownFieldHandle, MarkdownFieldProps>(
  function MarkdownField({label, onChange, error, minHeight = 200}, ref) {
    const editor = useMarkdownEditor({
      allowHTML: false,
      initial: {mode: 'wysiwyg', toolbarVisible: true},
    });

    React.useImperativeHandle(
      ref,
      () => ({getValue: () => editor.getValue(), clear: () => editor.clear()}),
      [editor],
    );

    React.useEffect(() => {
      if (!onChange) return undefined;
      const handler = () => onChange(editor.getValue());
      editor.on('change', handler);
      return () => {
        editor.off('change', handler);
      };
    }, [editor, onChange]);

    return (
      <Flex direction="column" gap={1}>
        <Text variant="subheader-1">{label}</Text>
        <div
          style={{
            minHeight,
            border: '1px solid var(--g-color-line-generic)',
            borderRadius: 'var(--g-border-radius-m)',
            overflow: 'auto',
          }}
        >
          <MarkdownEditorView stickyToolbar={false} editor={editor} />
        </div>
        {error ? (
          <Text variant="caption-2" color="danger">
            {error}
          </Text>
        ) : null}
      </Flex>
    );
  },
);
EOF
cat > src/App.tsx <<'EOF'
import React from 'react';
import {Button, Card, Flex, Text, TextInput} from '@gravity-ui/uikit';
import {MarkdownField, type MarkdownFieldHandle} from './MarkdownField';

export function App() {
  const [title, setTitle] = React.useState('');
  const [error, setError] = React.useState<string>();
  const [submitted, setSubmitted] = React.useState<{title: string; body: string}>();
  const bodyRef = React.useRef<MarkdownFieldHandle>(null);

  const handleBodyChange = React.useCallback((value: string) => {
    if (value.trim()) setError(undefined);
  }, []);

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    const body = bodyRef.current?.getValue() ?? '';
    if (!body.trim()) {
      setError('Введите текст');
      return;
    }
    setSubmitted({title, body});
  };

  return (
    <form onSubmit={handleSubmit} style={{padding: 24, maxWidth: 800, margin: '0 auto'}}>
      <Flex direction="column" gap={4}>
        <Text variant="header-1">Новая заметка</Text>
        <TextInput
          label="Заголовок"
          placeholder="Заголовок"
          value={title}
          onUpdate={setTitle}
        />
        <MarkdownField
          ref={bodyRef}
          label="Текст (markdown)"
          onChange={handleBodyChange}
          error={error}
        />
        <Flex>
          <Button type="submit" view="action" size="l">
            Отправить
          </Button>
        </Flex>
        {submitted ? (
          <Card view="outlined" type="container" style={{padding: 16}}>
            <Flex direction="column" gap={2}>
              <Text variant="subheader-1">{submitted.title || 'Без заголовка'}</Text>
              <Text variant="code-2" style={{whiteSpace: 'pre-wrap'}}>
                {submitted.body}
              </Text>
            </Flex>
          </Card>
        ) : null}
      </Flex>
    </form>
  );
}
